import math
from functools import lru_cache

def calculate_ways(n, k, len, array):
    MOD = 998244353

    @lru_cache(maxsize=None)
    def count_good_subsequences(start):
        if start >= n - 1:
            return 1

        count = 0
        for j in range(1, k + 1):
            has_negated = any(array[start + i] == -1 for i in range(len))
            if has_negated:
                count += count_good_subsequences(start + len)

        return count % MOD

    return count_good_subsequences(0)

