def count_good_ways(n, k, len, array):
    # Initialize dp table with modulo value
    dp = [[0 for _ in range(k+1)] for __ in range(n+1)]
    dp[0][0] = 1  # Base case: all zeros, k good ways

    # Iterate over each element in the array
    for i in range(n):
        # Initialize dp table for current element
        curr_dp = [0] * (k+1)
        for j in range(1, k+1):
            if array[i] == j:
                # Adjust from right-hand side
                for s in range(1, min(len-1, j) + 1):
                    for d in range(s, k):
                        curr_dp[d] = (curr_dp[d] + dp[i+s][d-s*k]) % (998244353)
                if i - s >= 0:
                    curr_dp[array[i]] = (curr_dp[array[i]] + dp[i+s][s*k + k][array[i] - 1]) % (998244353)
            else:
                # Adjust from left-hand side
                for s in range(1, min(len-1, k - j) + 1):
                    for d in range(s, k):
                        curr_dp[d] = (curr_dp[d] + dp[i-s-1][d-s*k]) % (998244353)
                if i - s >= 0:
                    curr_dp[array[i]-1] = (curr_dp[array[i]-1] + dp[i-s-1][s*k + k]) % (998244353)
        dp[i+1] = curr_dp

    return sum(dp[n], 1) % (998244353)

