from math import gcd
from collections import defaultdict

def lcm(x, y):
    return x * y // gcd(x, y)

def fraction_to_num(nums):
    merged_groups = defaultdict(set)
    for i, num in enumerate(nums):
        merged_groups[num] |= {i}
    return merged_groups

def exhaustive_cover(group_nums, k):
    if k > len(group_nums):
        return False
    mem = [0 for _ in range(k)]
    cols = {0: True}
    def dfs(last_index):
        if len(set(mem)) == k:
            return any(mem[i] <= mem[last_index] for i in range(k))
        for i, group in group_nums.items():
            if last_index >= len(group) or mem[i] < len(group):
                new_num = len(set(mem) | group_nums[i][mem[i] : last_index + 1])
                if new_num not in cols:
                    cols[new_num] = True
                    mem[i] = new_num
                    if dfs(last_index - 1):
                        return True
                    if any(mem[i] < mem[j] + 1 for j in range(i)):
                        cols[new_num] = False
            mem[i] = min(max(i, last_index - i), len(group) - i - 1)
        return False
    return any(dfs(len(m) - 1) for len(m) in group_nums.values())

