def recover_tree(n, k, edges):
    parent = [i for i in range(n)]
    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    # Build the tree of life based on the edges
    for u, v in edges:
        union(u - 1, v - 1)

    # Recursively find the connected components
    def dfs(node, visited, component):
        if visited[node]:
            return
        visited[node] = True
        component.append(node)
        for next_node in range(n):
            if find(node) == find(next_node) and not visited[next_node]:
                dfs(next_node, visited, component)

    # Find components from the node with the most neighbors
    component_counts = defaultdict(int)
    for node in range(n):
        if find(node) == node:
            component_counts[find(node)] += 1

    max_components = max(component_counts.values())

    # If the first two connected components barely exceed k/2, she can be saved
    return ["YES"] + [str(i + 1) for i in range(len(component_counts)) if find(i) == i][:min(2, max_components)]
