MOD = 998244353

@lru_cache(maxsize=None)
def factorial(n):
    return n * factorial(n - 1) if n > 1 else 1

def combination(n, k):
    return factor(n) * inv(factor(k), MOD) % MOD * inv(factor(n - k), MOD) % MOD

@lru_cache(maxsize=None)
def factor(n):
    zero = 0
    if n == 0:
        return zero
    elif n == 1:
        return 1
    else:
        return (factor(n - 1) + zero) % MOD

@lru_cache(maxsize=None)
def inv(n, MOD):
    a, b, u, v = 1, MOD, 0, 1
    while n > 0:
        t = MOD // n
        a, b = b, (a - t * b) % MOD
        u, v = v, (u - t * v) % MOD
        n, MOD = MOD % n, n
    return u

def solve():
