from bisect import bisect_left

class MaxPriorityQueue:
    def __init__(self):
        self.heap = deque()

    def insert(self, item):
        self.heap.append(item)
        end = len(self.heap) - 1
        parent_index = (end - 1) // 2
        while parent_index >= 0 and self.heap[parent_index] < self.heap[end]:
            self.heap[parent_index], self.heap[end] = self.heap[end], self.heap[parent_index]
            end = parent_index
            parent_index = (end - 1) // 2

    def remove(self):
        item = self.heap[0]
        self.heap[0], self.heap[-1] = self.heap[-1], self.heap[0]
        self.heap.pop()
        end = 0
        while (end * 2 + 1) < len(self.heap):
            index = end * 2 + 1
            if (end * 2 + 2) < len(self.heap) and self.heap[end * 2 + 2] > self.heap[index]:
                index = end * 2 + 2
            if self.heap[end] < self.heap[index]:
                self.heap[end], self.heap[index] = self.heap[index], self.heap[end]
                end = index
            else:
                break
