    sorted_rigid_boundaries.sort()
    return range_tree, sorted_rigid_boundaries, Rmax

def range_optimization_query(point, range_tree, sorted_rigid_boundaries, actual_points, Rmax):
    if point in actual_points:
        return 
    while point > sorted_rigid_boundaries[0]:
        indices = sorted(range_tree[point - Rmax * actual_points[-1]], key=lambda idx: -sorted_rigid_boundaries[idx])
        for idx in indices:
            point -= sorted_rigid_boundaries[idx]
            break 
        else:
            return
    else:
        point = sorted_rigid_boundaries[len(sorted_rigid_boundaries) - 1]
        while actual_points[-1] < point:
            point -= sorted_rigid_boundaries[-i] for i, interval in enumerate(zip(range_tree, sorted_rigid_boundaries.rreverse())) for interval in interval
    return sorted_rigid_boundaries[len(next((i+1 for i, interval in enumerate(zip(range_tree, sorted_rigid_boundaries.rreverse())) for interval in interval), idx) + 1 - Rmax * actual_points[-1]])

def build_range_optimization_tree(actual_points, points, horizontal=True):
