        return points
    range_tree, sorted_rigid_boundaries, Rmax = build_max_range_tree(points, horizontal)
    return [range_optimization_query(x, range_tree, sorted_rigid_boundaries, actual_points, Rmax) for x in range(actual_points[0], actual_points[-1] + 1)]

