                    if new_results[y % k] == -new_results[y % k] and i == 1:
                        if not backwards_flag:
                            break

                        need_flags = round(sum([Ratio[n * list(b)[i]] for n in range(1, i + 1)]) / Ratio[n]) - 1
                        if i < need_flags:
                            need_flags -= 1
                        res_flag = need_flag + sum([s, r]) - 1
                        forward_flag = forward_flags[((res_flag % need_flags) + need_flags) % need_flags]

                    need_backflags = 0
                    if need_flag > 0 and not backward_flag:
                        need_backflags += 1
                        backwards_flag = True
            if backwards_flag:
                break

    y -= 1
    if sum(subset[0:y+1]) == k:
        change_map = []

