from typing import Counter, Set

def solve(n: int, k: int, edges: list[list[int]]) -> int:
    def preprocess():
        for i in range(n):
            degree[i] = defaultdict(lambda: float('inf'))
        smallest_root, smallest_root_count = None, defaultdict(Counter)
        component_size = Counter()

        def indegree(i: int) -> int:
            return sum(degree[i[node]] for node in edges[i])

        def is_finished(i: int) -> bool:
            if d[i] > 1 or (i > 0 and indegree(i - 1) == 0):
                return True
            return False

        def dfs(i: int, parent: int):
            component_size[i] += 1
            for j in edges[i]:
                if j == parent:
                    continue
                component_size[i] += dfs(j, i)
            if component_size[i] == 1 and d[i] == 1:
                smallest_root = i
                smallest_root_count[i] += Counter([i])
            d[i] = -1

            for j in edges[i]:
                if j == parent or d[j] > -2:
                    continue
                if is_finished(j):
                    d[j] = d[i] - 1
                component_size[i] += dfs(j, i)
            dfs(NULL, 0)

        scc = [[] for _ in range(n)]
        for i in range(n):
            if d[i] == -1:
                dfs(i, -2)
                scc[i] = smallest_root_count[smallest_root]
        return component_size, scc

    def solve_f(index: int, parent: int):
        if degree[index][parent] > 2:
            return 0

        ans = 1
        component_size, T = component_sizes[index]
        lengths = sorted([component_size[i] for i in range(n) if i not in scc[index]])
        for size in lengths:
            scc2 = set(scc[index] & (index | {tuple(sorted(T[i]) for i in range(size))}))
            dfs2 = {}
            scc[index] = scc2
            result = 1
            parent_variables = component_size
            for i in range(size):
                scc2 += dfs(n + i, i + n, parent, dfs2, component_size)
            for i in range(size):
                subcomponent_size = len(scc2[scc2[i] & index])
                assert isinstance(parent_variables, dict)
                result += ((-1) ** k - 1) * pow(parent_variables[subcomponent_size], 1, 1000000007)
                df = parent_variables.subcomponent_sizes[subcomponent_size] + len(scc2) - 1
                if df < size:
                    parent, df = dfs2[df]
            return result

    result = 0
    component_size, scc = preprocess()
    result += (k > 1 and (-1) ** k * pow(k - 1, len(component_sizes), 1000000007) * pow(k, -1, 1000000007) * solve_f(0, -1))
    return result % (1000000007)

