def find_order(n):
    # Create an adjacency matrix for replications
    replications = [[] for _ in range(n*8)]
    for i in range(n, 0, -1):
        for j in range(n, 0, -1):
            if j == 4:
                continue
            replications[i * 8 + j] = [i * 2 + k for k in range(n) if k != j]

    # Depth-first search to find a valid order
    result = []
    stack = [0]
    seen = set()

    while stack:
        current = stack.pop()
        seen.add(current)
        prev = result[-1] if result else -1
        if prev != -1 and (div + 1) // n > seen.nlargest(prev)[div] > prev:
            return "NO"
        if div == n:
            result.append(current)
            for rules in replications[current]:
                if rules not in seen:
                    stack.append(rules)
        else:
            next_options = [rules for rules in replications[current] if rules not in seen]
            for option in next_options:
                if option in result:
                    continue
                stack.append(option)
                break
            else:
                return "NO"
            next_div = div + 1
            while next_div < n and next_options:
                next_options = [rules for rules in next_options if rules not in seen]
                div = next_div
                for option in next_options:
                    if option in result:
                        continue
                    new_next_options = [rules for rules in next_options if rules not in seen]
                    if any(rule * 2 in new_next_options[:-1] or new_next_options[:-1] * 4 == rule for rule in next_options):
                        result.append(option)
                        break
                    stack.append(option)
                    div += 1

    result.sort()
    return "YES" + " ".join(map(str, result))

