def modPowMod(base, exp, mod):
    result = 1
    base %= mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp // 2
        base = (base * base) % mod
    return result

def countWays(n, k, len, arr):
    dp = [[0] * (k + 1) for _ in range(len + 1)]
    dp[0][0] = 1

    for i in range(len + 1):
        for num in range(1, k + 1):
            if i - 1 >= 0:
                dp[i][num] = (dp[i-1][num] + dp[i][num-1]) % MOD
                # Only consider non-negative results
                if num > 0:
                    dp[i][num] = (dp[i][num] - dp[i-1][num-1]) % MOD

            dp[i][num] = (dp[i][num] + modPowMod(num, n - i - 1, MOD)) % MOD

    return modPowMod(dp[len][k], (1 << n) - 2, MOD)

